/bin/bash -lc "python - <<'PY'
import numpy as np
from scipy.ndimage import label
f=np.load('source_pixels.npz')['rgb'];
for i in range(96):
 a=f[i].astype(float);r,g,b=a.transpose(2,0,1)
 masks=[(b>r*1.25)&(b>g*1.12)&(b>60),(r>120)&(g>100)&(b<g*.65)]
 cs=[]
 for m in masks:
  ll,n=label(m)
  l=[]
  for k in range(1,n+1):
   y,x=np.where(ll==k)
   if len(x)>4:l.append((len(x),round(x.mean(),2),round(y.mean(),2),(x.min(),y.min(),x.max(),y.max())))
  cs.append(sorted(l,reverse=True)[:4])
 d=abs(a-f[max(0,i-1)].astype(float)).max(-1)
 if i<30 or i%5==0:print(i,'blue',cs[0],'yellow',cs[1], 'diff',int(d.sum()), 'bbox',np.where(d>20)[1].min(initial=256),np.where(d>20)[0].min(initial=144),np.where(d>20)[1].max(initial=0),np.where(d>20)[0].max(initial=0))
PY"
